    legend:{title:"표현 범례",territories:[alliedTerritory,axisTerritory],routes:[{side:"allied",label:"이탈리아군 공격"}],units:[{type:"infantry",side:"allied",label:"이탈리아군"},{type:"infantry",side:"axis",label:"오스트리아 제5군"}],colors:[{side:"allied",label:"파랑: 이탈리아군"},{side:"axis",label:"주황: 오스트리아군"}]}
