    legend:{title:"표현 범례",territories:[alliedTerritory,axisTerritory],routes:[{side:"allied",label:"영국·인도군 진격·구원"},{side:"axis",label:"포로 이송"}],units:[{type:"infantry",side:"allied",label:"인도군 제6사단"},{type:"infantry",side:"axis",label:"오스만 제6군"},{type:"ship",side:"allied",label:"구원군 보급"}],colors:[{side:"allied",label:"파랑: 영국·인도군"},{side:"axis",label:"주황: 오스만군"}]}
