    zones:[{kind:"control",side:"allied",coordinates:[[24.40,48.20],[25.70,48.10],[25.80,51.20],[24.70,51.30],[24.20,49.60]],label:"러시아군 진출(개략)",labelAt:[24.90,49.30]},{kind:"contested",side:"neutral",coordinates:[[25.30,48.20],[25.90,48.14],[26.00,51.20],[25.42,51.28],[25.20,49.60]],label:"공세 전 전선(개략)",labelAt:[25.66,50.40]}],
