    units:[{type:"bomber",side:"allied",at:[2.86,50.775],heading:90,label:"지뢰 폭파 지점",showLabel:false},{type:"infantry",side:"allied",at:[2.83,50.74],heading:40,label:"영국 제2군",showLabel:false},{type:"infantry",side:"axis",at:[2.93,50.78],heading:250,label:"독일 제4군",showLabel:false}],
