    zones:[{kind:"contested",side:"neutral",coordinates:[[24.30,48.90],[25.70,48.80],[25.90,49.80],[24.60,49.90],[24.10,49.30]],label:"갈리치아 공세 구역(개략)",labelAt:[24.90,49.20]}],
