    legend:{title:"표현 범례",territories:[alliedTerritory,axisTerritory],routes:[{side:"axis",label:"독일군 진격"},{side:"allied",label:"소비에트 대표단 이동"}],units:[{type:"infantry",side:"axis",label:"독일군"},{type:"truck",side:"allied",label:"소비에트 대표단"}],colors:[{side:"axis",label:"주황: 동맹국"},{side:"allied",label:"파랑: 소비에트 러시아"}]}
