    legend:{title:"표현 범례",territories:[alliedTerritory,axisTerritory],routes:[{side:"allied",label:"연합군 돌파·추격"}],units:[{type:"infantry",side:"allied",label:"사막기병군단"},{type:"bomber",side:"allied",label:"영국 공군"},{type:"infantry",side:"axis",label:"오스만군"}],colors:[{side:"allied",label:"파랑: 영국·아랍군"},{side:"axis",label:"주황: 오스만군"}]}
