    units:[{type:"tank",side:"allied",at:[2.62,49.86],heading:70,label:"연합군 전차",showLabel:false},{type:"bomber",side:"allied",at:[3.00,50.18],heading:60,label:"연합 항공대",showLabel:false},{type:"infantry",side:"axis",at:[3.50,50.14],heading:250,label:"독일군 후퇴",showLabel:false}],
    legend:{title:"표현 범례",territories:[alliedTerritory,axisTerritory],routes:[{side:"allied",label:"연합군 백일 공세"}],units:[{type:"tank",side:"allied",label:"연합군 전차"},{type:"bomber",side:"allied",label:"연합 항공대"},{type:"infantry",side:"axis",label:"독일군 후퇴"}],colors:[{side:"allied",label:"파랑: 협상국"},{side:"axis",label:"주황: 독일군"}]}
